"use client"

import { motion, useInView } from "framer-motion"
import { useRef, useEffect, useState } from "react"
import { SectionHeader } from "./section-header"
import { TelemetryChart } from "./telemetry-chart"

function ProgressMetric({
  label,
  value,
  index,
}: {
  label: string
  value: number
  index: number
}) {
  const ref = useRef<HTMLDivElement>(null)
  const isInView = useInView(ref, { once: true })
  const [displayValue, setDisplayValue] = useState(0)

  useEffect(() => {
    if (!isInView) return
    const duration = 1200
    const startTime = performance.now()
    function tick(now: number) {
      const elapsed = now - startTime
      const progress = Math.min(elapsed / duration, 1)
      const eased = 1 - Math.pow(1 - progress, 3)
      setDisplayValue(Math.round(value * eased))
      if (progress < 1) requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }, [isInView, value])

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0 }}
      whileInView={{ opacity: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.08 }}
      className="flex flex-col gap-2"
    >
      <div className="flex items-center justify-between">
        <span className="font-mono text-[10px] tracking-[0.15em] text-muted-foreground uppercase">
          {label}
        </span>
        <span className="font-mono text-xs text-foreground tabular-nums">
          {displayValue}%
        </span>
      </div>
      <div className="h-px w-full bg-border">
        <motion.div
          className="h-px bg-foreground/50"
          initial={{ width: "0%" }}
          animate={isInView ? { width: `${value}%` } : {}}
          transition={{ duration: 1.2, ease: "easeOut", delay: index * 0.08 }}
        />
      </div>
    </motion.div>
  )
}

function MetricValue({
  label,
  value,
  unit,
  index,
}: {
  label: string
  value: string
  unit: string
  index: number
}) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      whileInView={{ opacity: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.08 }}
      className="flex flex-col gap-1"
    >
      <span className="font-mono text-[10px] tracking-[0.15em] text-muted-foreground/50 uppercase">
        {label}
      </span>
      <div className="flex items-baseline gap-1">
        <span className="font-mono text-lg font-light text-foreground tabular-nums">{value}</span>
        <span className="font-mono text-[10px] text-muted-foreground">{unit}</span>
      </div>
    </motion.div>
  )
}

export function TelemetryPanel() {
  return (
    <section className="relative px-6 py-32">
      <SectionHeader
        label="03"
        title="TELEMETRY"
        subtitle="Real-time performance metrics and system diagnostics"
      />

      <div className="mx-auto flex max-w-4xl flex-col gap-16">
        {/* Progress metrics */}
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
          <ProgressMetric label="Similarity Index" value={87} index={0} />
          <ProgressMetric label="Confidence" value={94} index={1} />
          <ProgressMetric label="Anomaly Rate" value={23} index={2} />
          <ProgressMetric label="Signal Integrity" value={99} index={3} />
        </div>

        {/* Metric values */}
        <div className="grid grid-cols-2 gap-8 sm:grid-cols-4">
          <MetricValue label="Frame Rate" value="60.0" unit="fps" index={0} />
          <MetricValue label="Processing" value="124" unit="ms" index={1} />
          <MetricValue label="Bandwidth" value="2.4" unit="GB/s" index={2} />
          <MetricValue label="Detections" value="3" unit="events" index={3} />
        </div>

        {/* Telemetry charts */}
        <div className="grid grid-cols-1 gap-8 sm:grid-cols-2">
          <TelemetryChart label="RGB Delta" height={56} />
          <TelemetryChart label="Thermal Variance" height={56} />
          <TelemetryChart label="Fusion Confidence" height={56} />
          <TelemetryChart label="Anomaly Probability" height={56} />
        </div>

        {/* System status */}
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="flex flex-wrap items-center justify-center gap-x-8 gap-y-3 border-t border-border pt-8"
        >
          {[
            { label: "Core Temp", value: "42.3 C" },
            { label: "Memory", value: "67%" },
            { label: "GPU", value: "89%" },
            { label: "Network", value: "Stable" },
          ].map((item) => (
            <div key={item.label} className="flex items-center gap-2">
              <span className="font-mono text-[10px] tracking-wider text-muted-foreground/40 uppercase">
                {item.label}
              </span>
              <span className="font-mono text-[10px] text-muted-foreground">
                {item.value}
              </span>
            </div>
          ))}
        </motion.div>
      </div>
    </section>
  )
}
